    {
        ItemType = other.ItemType; NumberOfItems = other.NumberOfItems;
        PPerItemData[0] = other.PPerItemData[0]; PPerItemData[1] = other.PPerItemData[1];
        AverageBoughtPrice = other.AverageBoughtPrice;
        ++g_assigns;
        return *this;
    }
