    /* sort the keys (tiny insertion sort) so the map is ordered */
    for (int i = 1; i < 7; ++i) for (int j = i; j > 0 && keys[j - 1] > keys[j]; --j) { unsigned int t = keys[j]; keys[j] = keys[j - 1]; keys[j - 1] = t; }
